-- Stage English, Grade 9. Inactive until final activation; legacy rows remain available.
DO $stage_one_catalog$
DECLARE
  v_catalog jsonb := $payload${"subject":"English","grade":9,"strand_count":15,"sub_strand_count":75,"source_name":"KICD Junior School Curriculum Design - English Grade 9 (Rationalized 2024)","source_url":"https://drive.google.com/file/d/1ehe01q4q8G-ft1PsA0r7skcz6grZfiNQ/preview","source_note":"Official KICD Grade 9 index: https://kicd.ac.ke/cbc-materials/curriculum-designs/grade-nine-designs/ Current public viewer: https://drive.google.com/file/d/1ehe01q4q8G-ft1PsA0r7skcz6grZfiNQ/preview. Numbered two-level hierarchy transcribed from the grade summary; no topics tier. Report: research/verified-20260929/04-english.md","strands":[{"strand_name":"THEME 1.0: CITIZENSHIP","order":1,"sub_strands":[{"sub_strand_name":"1.1.1 Polite Language -Euphemism","order":1},{"sub_strand_name":"1.2.1 Independent reading-Grade appropriate texts","order":2},{"sub_strand_name":"1.3.1 Gender neutral language","order":3},{"sub_strand_name":"1.4.1 Class reader – Structure and setting","order":4},{"sub_strand_name":"1.5.1 Legibility and neatness","order":5}]},{"strand_name":"THEME 2.0: SCIENCE: FICTION","order":2,"sub_strands":[{"sub_strand_name":"2.1.1 Oral Literature-Short forms","order":1},{"sub_strand_name":"2.2.1 Intensive reading-Simple poems","order":2},{"sub_strand_name":"2.3.1 Nouns and quantifiers","order":3},{"sub_strand_name":"2.4.1 Class reader- Plot","order":4},{"sub_strand_name":"2.5.1 Punctuation marks","order":5}]},{"strand_name":"THEME 3.0: ENVIRONMENTAL CONSERVATION","order":3,"sub_strands":[{"sub_strand_name":"3.1.1 Listening comprehension –Grade appropriate texts (main idea and specific details","order":1},{"sub_strand_name":"3.2.1 Reading for information and meaning","order":2},{"sub_strand_name":"3.3.1 Modal auxialiaries","order":3},{"sub_strand_name":"3.4.1 Poems -Structure","order":4},{"sub_strand_name":"3.5.1 Structure of a paragraph","order":5}]},{"strand_name":"THEME 4.0: CONSUMER PROTECTION: CONSUMER LAWS AND POLICIES","order":4,"sub_strands":[{"sub_strand_name":"4.1.1 Selective listening","order":1},{"sub_strand_name":"4.2.1 Intensive reading-Key events","order":2},{"sub_strand_name":"4.3.1 Present and Past Perfect Aspect","order":3},{"sub_strand_name":"4.4.1 Class reader -characters","order":4},{"sub_strand_name":"4.5.1 Descriptive Paragraph Narrative and Descriptive Paragraphs","order":5}]},{"strand_name":"THEME 5.0 RELATIONSHIPS: COMMUNITY","order":5,"sub_strands":[{"sub_strand_name":"5.1.1 Pronunciation","order":1},{"sub_strand_name":"5.2.1 Reference materials","order":2},{"sub_strand_name":"5.3.1 Order of Adjectives","order":3},{"sub_strand_name":"5.4.1 Class reader –Style","order":4},{"sub_strand_name":"5.5.1 Letter of application","order":5}]},{"strand_name":"THEME 6.0: LEISURE TIME","order":6,"sub_strands":[{"sub_strand_name":"6.1.1 Conversational skills -Negotiation skills","order":1},{"sub_strand_name":"6.2.1 Reading fluency","order":2},{"sub_strand_name":"6.3.1 Comparison of Adverbs","order":3},{"sub_strand_name":"6.4.1 Class reader- Themes","order":4},{"sub_strand_name":"6.5.1 Spelling","order":5}]},{"strand_name":"THEME 7.0: NATURAL RESOURCES: MARINE LIFE","order":7,"sub_strands":[{"sub_strand_name":"7.1.1 Listening for details","order":1},{"sub_strand_name":"7.2.1 Intensive reading-Interpretation and evaluation","order":2},{"sub_strand_name":"7.3.1 Relative Pronouns, Interrogative Pronouns","order":3},{"sub_strand_name":"7.4.1 Class Reader- (Intensive reading) characters","order":4},{"sub_strand_name":"7.5.1 The writing process -Steps","order":5}]},{"strand_name":"THEME 8.0: TOURISM: INTERNATIONAL","order":8,"sub_strands":[{"sub_strand_name":"8.1.1 Oral Poetry","order":1},{"sub_strand_name":"8.2.1 Reading for interpretation","order":2},{"sub_strand_name":"8.3.1 Complex Prepositions","order":3},{"sub_strand_name":"8.4.1 Poetry-Characters","order":4},{"sub_strand_name":"8.5.1 Assessing writing","order":5}]},{"strand_name":"THEME 9.0: HEROES AND HEROINES: WORLD","order":9,"sub_strands":[{"sub_strand_name":"9.1.1 Diphthongs and sentence stress","order":1},{"sub_strand_name":"9.2.1 Extensive reading- Grade appropriate fiction","order":2},{"sub_strand_name":"9.3.1 Conjunctions-Correlative conjunctions","order":3},{"sub_strand_name":"9.4.1 Class reader -Style","order":4},{"sub_strand_name":"9.5.1 Narrative Composition","order":5}]},{"strand_name":"THEME 10.0: SOCIAL AND MASS MEDIA","order":10,"sub_strands":[{"sub_strand_name":"10.1.1 Impromptu Speeches","order":1},{"sub_strand_name":"10.2.1 Study skills –Note making","order":2},{"sub_strand_name":"10.3.1 Determiners –Numerals and Ordinals","order":3},{"sub_strand_name":"10.4.1 Class reader- Play (project)","order":4},{"sub_strand_name":"10.5.1 Filling forms-Application forms","order":5}]},{"strand_name":"THEME 11.0: INCOME GENERATING ACTIVITIES","order":11,"sub_strands":[{"sub_strand_name":"11.1.1 Conversation skills- Job Interviews","order":1},{"sub_strand_name":"11.2.1 Extensive Reading -Fiction","order":2},{"sub_strand_name":"11.3.1 Nouns","order":3},{"sub_strand_name":"11.4.1 Class reader- Lessons learnt","order":4},{"sub_strand_name":"11.5.1 Mechanics of writing-Abbreviations and Acronyms","order":5}]},{"strand_name":"THEME 12.0: PERSONAL GROOMING","order":12,"sub_strands":[{"sub_strand_name":"12.1.1 Listening to respond-Expressing feelings","order":1},{"sub_strand_name":"12.2.1 Intensive Reading-Comprehension Strategies","order":2},{"sub_strand_name":"12.3.1 Phrasal verbs","order":3},{"sub_strand_name":"12.4.1 Class reader-Characterisation","order":4},{"sub_strand_name":"12.5.1 The Writing process","order":5}]},{"strand_name":"THEME 13.0: SEA TRAVEL","order":13,"sub_strands":[{"sub_strand_name":"13.1.1 Extensive listening- Speeches","order":1},{"sub_strand_name":"13.2.1 Intensive Reading –Visualising and Summarising","order":2},{"sub_strand_name":"13.3.1 Complex Sentences","order":3},{"sub_strand_name":"13.4.1 Class reader –Style","order":4},{"sub_strand_name":"13.5.1 Creative writing: Idioms","order":5}]},{"strand_name":"THEME 14.0: SPORTS – WORLD CUP (FOOTBALL)","order":14,"sub_strands":[{"sub_strand_name":"14.1.1 Intonation in sentences-question tags","order":1},{"sub_strand_name":"14.2.1 Summarising-argumentative texts","order":2},{"sub_strand_name":"14.3.1 Direct and Indirect Speech","order":3},{"sub_strand_name":"14.4.1 Class reader- Relating characters and themes to real life","order":4},{"sub_strand_name":"14.5.1 Descriptive writing","order":5}]},{"strand_name":"THEME 15.0: TOURIST ATTRACTION SITES- WORLD","order":15,"sub_strands":[{"sub_strand_name":"15.1.1 Oral reports- News (role play)","order":1},{"sub_strand_name":"15.2.1 Reading Fluency","order":2},{"sub_strand_name":"15.3.1 Imperatives (Commands, requests) and exclamatory sentences","order":3},{"sub_strand_name":"15.4.1 Intensive reading-Poems","order":4},{"sub_strand_name":"15.5.1 Emails","order":5}]}]}$payload$::jsonb;
  v_grade_id uuid;
  v_subject_id uuid;
  v_source_id uuid;
  v_strand_id uuid;
  v_strand jsonb;
  v_sub_strand jsonb;
  v_strands integer := 0;
  v_sub_strands integer := 0;
BEGIN
  IF EXISTS (SELECT 1 FROM public.curriculum_sources WHERE source_name = v_catalog->>'source_name' LIMIT 1) THEN
    RAISE EXCEPTION 'Source already staged: %', v_catalog->>'source_name';
  END IF;
  SELECT id INTO v_grade_id FROM public.curriculum_grades
    WHERE grade_number = (v_catalog->>'grade')::integer AND curriculum_type = 'CBE' LIMIT 1;
  IF v_grade_id IS NULL THEN RAISE EXCEPTION 'CBE Grade % missing.', v_catalog->>'grade'; END IF;
  SELECT id INTO v_subject_id FROM public.curriculum_subjects
    WHERE grade_id = v_grade_id AND subject_name = v_catalog->>'subject' LIMIT 1;
  IF v_subject_id IS NULL THEN RAISE EXCEPTION 'CBE Grade % subject missing: %.', v_catalog->>'grade', v_catalog->>'subject'; END IF;

  INSERT INTO public.curriculum_sources (source_name, source_url, source_type, license_status, retrieval_status, notes)
  VALUES (v_catalog->>'source_name', v_catalog->>'source_url', 'official_design', 'official_public', 'approved', v_catalog->>'source_note')
  RETURNING id INTO v_source_id;
  UPDATE public.curriculum_subjects SET curriculum_source_id = v_source_id WHERE id = v_subject_id;

  FOR v_strand IN SELECT value FROM jsonb_array_elements(v_catalog->'strands') LOOP
    INSERT INTO public.curriculum_strands (subject_id, strand_name, strand_description, strand_order, is_current)
    VALUES (v_subject_id, v_strand->>'strand_name', 'Official KICD source-verified curriculum. Provenance is linked through curriculum_subjects.curriculum_source_id.', (v_strand->>'order')::integer, false)
    RETURNING id INTO v_strand_id;
    v_strands := v_strands + 1;
    FOR v_sub_strand IN SELECT value FROM jsonb_array_elements(v_strand->'sub_strands') LOOP
      INSERT INTO public.curriculum_sub_strands (strand_id, sub_strand_name, sub_strand_description, sub_strand_order, is_current)
      VALUES (v_strand_id, v_sub_strand->>'sub_strand_name', 'Official KICD source-verified sub-strand; no third-tier topic record is created.', (v_sub_strand->>'order')::integer, false);
      v_sub_strands := v_sub_strands + 1;
    END LOOP;
  END LOOP;

  IF v_strands <> (v_catalog->>'strand_count')::integer OR v_sub_strands <> (v_catalog->>'sub_strand_count')::integer THEN
    RAISE EXCEPTION 'Catalog count mismatch for % Grade %: strands %/%, sub-strands %/%',
      v_catalog->>'subject',v_catalog->>'grade',v_catalog->>'strand_count',v_strands,v_catalog->>'sub_strand_count',v_sub_strands;
  END IF;
END
$stage_one_catalog$;
